var o=`0467-gozleme`;var t=`world-0467`;var i=`TR`;var a=`western-asia`;var r=8;var l=52;var s={en:`Gözleme`,ua:`Гезлеме`};var u={en:`A traditional dish from Türkiye, centered on all-purpose flour, spinach, feta, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: пшеничне борошно універсальне, шпинат, фета, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,400,`g`],[`water`,210,`ml`],[`table-salt`,6,`g`],[`extra-virgin-olive-oil`,25,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:7,i:[[`spinach`,300,`g`],[`feta`,180,`g`],[`yellow-onion`,100,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`unsalted-butter`,60,`g`]]}];var d={slug:o,id:t,country:`TR`,region:a,servings:8,minutes:52,title:s,text:u,steps:g};export{i as country,d as default,t as id,l as minutes,a as region,r as servings,o as slug,g as steps,u as text,s as title};